	sections = {
		{
			title = "Resumo",
			text = [=[O Sacerdote das Sombras Sarvis cuida da capela ao pé da colina em {link:deathknell}Plangemortis{/link}. Quando os recém-erguidos saem cambaleando da cripta, frios e confusos, é Sarvis quem lhes conta a verdade. Eles estão mortos. Estão livres do Lich Rei. E agora pertencem à Dama Sombria, que lidera os {link:forsaken}Renegados{/link} em sua guerra contra o {link:scourge}Flagelo{/link} e contra os humanos que os caçam.]=],
		},
		{
			title = "Importância",
			text = [=[Sarvis dá aos novos {link:forsaken}Renegados{/link} seu primeiro propósito. Ele os envia contra os mortos sem mente da aldeia, os antigos irmãos e irmãs que não puderam ser trazidos para o rebanho.]=],
