		{ id = "undertaker-mordo", name = "Coveiro Mordo", note = "envia-lhe os erguidos" },
		{ id = "executor-arren", name = "Executor Arren", note = "comanda Plangemortis" },
	},
})

Translate("ptBR", "undertaker-mordo", {
	title = "Coveiro Mordo",
	subtitle = "Guardião da Cripta",
	found = "Diante da cripta de Plangemortis",
	hint = [=[Fale com o coveiro que espera do lado de fora da cripta de Plangemortis.]=],
	allegiance = "Renegados",
	aliases = { "Mordo" },
	sections = {
		{
			title = "Resumo",
			text = [=[Mordo é o coveiro de {link:deathknell}Plangemortis{/link} e o guardião de sua cripta. Muitas vezes é o primeiro rosto que um novo Renegado vê. Ele não finge que o despertar é gentil. Os corpos que não se mexem são queimados, e ele diz com franqueza que muitos dos que se erguem quase foram para o fogo junto com eles.]=],
		},
		{
			title = "Importância",
			text = [=[Mordo está no limiar da segunda vida dos {link:forsaken}Renegados{/link}. Todos os que despertam em {link:deathknell}Plangemortis{/link} passam por suas mãos, e ele envia cada um deles à capela lá embaixo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Guarda a cripta de {link:deathknell}Plangemortis{/link} e cuida dos mortos trazidos para lá.
• Envia os recém-erguidos ao {link:shadow-priest-sarvis}Sacerdote das Sombras Sarvis{/link}.]=],
		},
	},
	mentions = {
		{ text = "Despertar Brusco" },
	},
	bonds = {
		{ id = "shadow-priest-sarvis", name = "Sacerdote das Sombras Sarvis", note = "recebe os erguidos" },
	},
})

Translate("ptBR", "executor-arren", {
	title = "Executor Arren",
	subtitle = "Executor de Plangemortis",
	found = "Plangemortis",
	hint = "Fale com o executor que comanda Plangemortis.",
	allegiance = "Renegados · Guarda da Morte",
	aliases = { "Arren" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Executor Arren comanda {link:deathknell}Plangemortis{/link}. Tem poucos soldados e muitos problemas. Aranhas tomaram a mina de ouro de que seu povo precisa, e um acampamento da {link:scarlet-crusade}Cruzada Escarlate{/link} surgiu a sudeste. Ele responde ao {link:executor-zygand}Executor Zygand{/link}, em {link:brill}Montalvo{/link}, e envia todo recruta capaz para resolver o que sua Guarda da Morte não consegue.]=],
		},
		{
			title = "Importância",
			text = [=[Arren é um comandante prático. Zomba dos fanáticos que não ouvem a razão, e conhece o valor de uma carta capturada.]=],
		},
		{
			title = "Feitos",
