Translate("ptBR", "garek-bandarion", {
	title = "Garek Bandarion",
	subtitle = "O Primeiro Paladino Renegado",
	found = "Lembrado em Bandarion Keep",
	hint = "Procure a fortaleza nas colinas do oeste que leva seu nome.",
	allegiance = [=[Renegados · Guarda da Morte · antes, a Guarda da Cidade de Lordaeron]=],
	aliases = { "Garek", "Capitão Bandarion" },
	sections = {
		{
			title = "Resumo",
			text = [=[Garek Bandarion foi um soldado de {link:lordaeron}Lordaeron{/link} que morreu em sua queda e se ergueu entre os {link:forsaken}Renegados{/link}. Tornou-se o primeiro capitão da Guarda da Morte, e foi o primeiro dos Renegados a empunhar a {link:holy-light}Luz Sagrada{/link} como paladino. Tombou quando a necrópole {red:naxxramas}Naxxramas{/red} veio contra a {link:undercity}Cidade Baixa{/link}. Os paladinos de {link:tyr-s-watch}Tyr's Watch{/link} deram seu nome ao monastério, e ainda gritam seu nome como brado de batalha.]=],
		},
		{
			title = "Importância",
			text = [=[Para os paladinos {link:forsaken}Renegados{/link}, Garek é a prova de que a Luz não os abandonou na morte. Para a Guarda da Morte, é o capitão que formou suas fileiras. Sua vida liga os últimos dias do reino vivo aos primeiros dias do reino morto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Em vida, serviu na Guarda da Cidade da capital sob o Capitão Landen, que o escolheu como sucessor.
• No dia em que {link:arthas-menethil}Arthas{/link} assassinou o pai, ele e Landen conduziram sobreviventes para fora pelos esgotos sob a cidade.
• Vingou-se do Barão Rivendare, o senhor que traiu o reino ao {link:cult-of-the-damned}Culto dos Malditos{/link}, e morreu de seus ferimentos e da praga.
• Como Renegado, lutou ao lado da {link:dark-ranger-anya}Patrulheira Sombria Anya{/link} nos primeiros dias da {link:undercity}Cidade Baixa{/link}.
• Chegou a capitão da Guarda da Morte.
• Morreu na defesa da Cidade Baixa contra Naxxramas.]=],
		},
	},
	chapters = {
		{
			title = "Os Últimos Dias de Lordaeron",
			hint = [=[Descubra o que os Renegados da Cidade Baixa dizem de seu primeiro capitão.]=],
			text = [=[Garek era um jovem guarda que ansiava pela batalha, e seu capitão, Landen, lhe dizia que proteger o povo era a glória maior. Na noite em que {link:arthas-menethil}Arthas{/link} matou o Rei {link:terenas-menethil}Terenas Menethil{/link}, eles encontraram a sala do trono cheia de cultistas. {link:uther-the-lightbringer}Uther, o Arauto da Luz{/link}, os enviou para salvar quem pudessem. Sob a cidade, descobriram que o culto estava pronto havia muito tempo. Landen ficou para trás para conter {link:the-baron}o Barão{/link} Rivendare, para que Garek pudesse levar o povo a um lugar seguro. Garek nunca perdoou o barão. Caçou-o até Stratholme e o matou ali, e morreu de seus ferimentos.]=],
		},
		{
			title = "Uma Segunda Vida",
			hint = "Ouça os paladinos de Bandarion Keep falarem de seu fundador.",
			text = [=[Garek despertou nas criptas da {link:undercity}Cidade Baixa{/link} sem nenhuma lembrança além do próprio nome. O boticário Putress queria usar seu corpo como peças. A {link:dark-ranger-anya}Patrulheira Sombria Anya{/link} o impediu. Garek jurou lealdade a {link:sylvanas-windrunner}Sylvanas{/link} e, com Anya, reuniu os mortos de livre-arbítrio das ruínas, limpou os túneis e ajudou a cidade a crescer. Quando a {link:scarlet-crusade}Cruzada Escarlate{/link} rompeu as muralhas da Cidade Baixa, ele liderou a Guarda da Morte contra ela. Em algum momento desses anos, a Luz voltou a lhe responder.]=],
		},
		{
			title = "A Fortaleza de Seu Nome",
			hint = [=[Descubra por que a fortaleza de Northface Rock leva seu nome.]=],
			text = [=[Quando Naxxramas chegou às ruínas da capital, os {link:forsaken}Renegados{/link} e a {link:argent-dawn}Aurora Argêntea{/link} a combateram juntos na superfície. Garek não voltou. {link:danitha-morr}Danitha Morr{/link} e {link:leonid-barthalomew}Leonid Barthalomew{/link} lutaram nessa batalha e perderam muitos amigos ali. Quando Danitha tomou a velha fortaleza de {link:bandarion-keep}Northface Rock{/link} para sua ordem, deu-lhe o nome dele.]=],
		},
	},
	mentions = {
		{ text = "Uma Causa Justa" },
		{ text = "{link:bandarion-keep}Bandarion Keep{/link}" },
		{ text = "A Justiça da Luz" },
	},
	bonds = {
		{ id = "dark-ranger-anya", name = "Patrulheira Sombria Anya", note = "sua companheira" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "deu seu nome à fortaleza" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "um amigo" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sua rainha" },
	},
})

Translate("ptBR", "dark-ranger-anya", {
	title = "Patrulheira Sombria Anya",
	subtitle = "Patrulheira Sombria da Rainha Banshee",
	found = "Desconhecido nestes dias",
	hint = "Conheça-a pelas histórias de Garek Bandarion.",
	allegiance = "Renegados · antes, os Andarilhos de Quel'Thalas",
	aliases = { "Anya" },
	sections = {
		{
			title = "Resumo",
			text = [=[Anya é uma patrulheira sombria, uma das elfas mortas-vivas que servem a {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. Em vida, foi patrulheira de {link:quel-thalas}Quel'Thalas{/link} sob o comando de Sylvanas. Morreu defendendo sua terra natal contra o {link:scourge}Flagelo{/link} e se ergueu como sua escrava. Ela se lembra de tudo o que fez nesse tempo. Quando se libertou, Sylvanas lhe deu um lugar a que pertencer, e por isso Anya deu à Dama Sombria sua lealdade para sempre.]=],
		},
		{
			title = "Importância",
			text = [=[Anya é uma das primeiras patrulheiras sombrias dos {link:forsaken}Renegados{/link}, e uma das que viram a {link:undercity}Cidade Baixa{/link} surgir dos túneis. Foi companheira de {link:garek-bandarion}Garek Bandarion{/link} nas primeiras guerras do reino morto. Onde ele perdeu suas lembranças, ela guardou todas as suas, e lhe ensinou que, para muitos Renegados, a morte é uma folha em branco e uma segunda vida. Ela confia muito pouco nos vivos. Quando um paladino da antiga Punho de Prata mostrou misericórdia a um trabalhador Renegado e seu capitão matou o homem mesmo assim, Anya disse a Garek que os vivos jamais veriam os mortos-vivos como pessoas, e que não se podia confiar neles.]=],
		},
		{
			title = "Feitos",
			text = [=[• Tombou na defesa de {link:quel-thalas}Quel'Thalas{/link} e fez coisas terríveis como escrava do Lich Rei.
• Impediu que o boticário Putress retalhasse {link:garek-bandarion}Garek{/link} para usá-lo como peças quando ele despertou.
• Disse a Garek que sua memória perdida era uma misericórdia, pois ela se lembrava bem demais dos próprios crimes.
• Com Garek, resgatou os mortos de livre-arbítrio das ruínas da capital.
• Lutou ao lado dele contra a {link:scarlet-crusade}Cruzada Escarlate{/link} e contra Naxxramas.
• Com {link:sylvanas-windrunner}Sylvanas{/link} e a patrulheira sombria Clea, cavalgou até o {link:the-marris-stead}Sítio dos Marris{/link} em busca de {link:nathanos-blightcaller}Nathanos Marris{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica destes dias registra onde Anya serve agora, nem o que fez depois que {link:garek-bandarion}Garek{/link} tombou.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "seu companheiro" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "sua rainha" },
	},
})

Translate("ptBR", "danitha-morr", {
	title = "Danitha Morr",
	subtitle = "Comandante de Bandarion Keep",
	found = "Bandarion Keep",
	hint = "Fale com a líder dos paladinos em Bandarion Keep.",
