	},
	chapters = {
		{
			title = "Um Lar nas Colinas",
			hint = [=[Encontre o caminho até Bandarion Keep e conheça sua comandante.]=],
			text = [=[A fortaleza era uma ruína quando os paladinos de Danitha chegaram. {link:murlocs}Murlocs{/link} Vile Fin haviam feito dela um local de desova, e lutavam para retomá-la mesmo depois de expulsos. Danitha tinha poucos materiais, menos aliados ainda e muitíssimas muralhas para consertar. Ela recebia bem todo recém-chegado que ainda se apegasse à Luz.]=],
		},
		{
			title = "Os Maculados",
			hint = [=[Resolva a questão dos paladinos erguidos que fizeram de Shadowvale seu covil.]=],
			text = [=[Nem todo paladino que se ergue consegue aceitar o que se tornou. Alguns guardam os ódios de suas antigas vidas e matam os {link:forsaken}Renegados{/link} que encontram. Cada uma dessas mortes torna mais fácil para os inimigos da ordem espalhar o medo. Danitha mandou destruir os Maculados de {link:shadowvale}Shadowvale{/link} e decapitar seu comandante, {link:rudolph-gelhardt}Rudolph Gelhardt{/link}.]=],
		},
		{
			title = "Um Sinal de Boa-fé",
			hint = "Leve o presente de Danitha à Dama Sombria.",
			text = [=[Danitha enviou a cabeça de {link:rudolph-gelhardt}Gelhardt{/link} à {link:undercity}Cidade Baixa{/link}, para mostrar à Dama Sombria que {link:tyr-s-watch}Tyr's Watch{/link} mantém a própria casa em ordem. {link:sylvanas-windrunner}Sylvanas{/link} não duvidou da sinceridade de Danitha. Disse que esperava que mais paladinos enlouquecessem, e que um dia poderia decidir não tolerar mais a ordem. Disse a seus paladinos que servissem bem, e que ela estaria observando.]=],
		},
	},
	mentions = {
		{ text = "Conhecendo o Terreno" },
		{ text = "Os Maculados" },
		{ text = "Um Sinal de Boa-fé" },
		{ text = "Uma Lição de Divindade" },
		{ text = "Incidente Diplomático" },
		{ text = "Uma Causa Justa" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "um amigo tombado" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "um velho camarada" },
		{ id = "rudolph-gelhardt", name = "Rudolph Gelhardt", note = "o comandante dos Maculados" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "desconfia de sua ordem" },
	},
})

